"""Build a self-contained DM key viewer; map files remain beside the guide."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
data=[
 {'id':'g1','title':'G1 — Utility Cut','file':'G1-Utility-Cut.png','note':'Dua jalur ke G2. Pintu tidak terkunci; tidak ada musuh default.','keys':[['Entry','M15','Datang/pulang dari jalan utilitas'],['Ramp','G5','Pendekatan kering'],['Maintenance','S5','Jalur basah kanan'],['G2','L2','Threshold menuju receiving hall'],['Shack','U8','Dressing; bukan clue wajib']]},
 {'id':'g2','title':'G2 — Receiving Hall','file':'G2-Receiving-Hall.png','note':'Slip mengantar ke K-17 tanpa check. OFF aman; ON memberi warning alat G4.','keys':[['Entry','L15','Dari G1'],['Slip','C8','Laci meja: G-B; ambil dari sisi yang terjangkau'],['Panel','W7','HANDLING / OFF; circuit G4'],['Footprints','U13','Jejak baru dan tali pengikat'],['G3','L2','Ke archive']]},
 {'id':'g3','title':'G3 — Archive / Packing','file':'G3-Archive-Packing.png','note':'Kotak tidak terkunci/terjebak. Dokumen bukan bagian kontrak; pemilik tetap unknown.','keys':[['Entry','L15','Dari G2'],['Notes','G7','Meja penelitian'],['Sketch','G11','G-C; boleh pindah ke meja atas'],['Ritual','S9','Bersih, tidak aktif, bukan portal'],['K-17','V4','Rak alcove; kotak adalah objek, bukan NPC'],['G4','L2','Pilihan keluar via dispatch bay']]},
 {'id':'g4','title':'G4 — Dispatch Bay','file':'G4-Dispatch-Bay.png','note':'Opsional. Crew ATAU alat sebagai sumber fight; kedua sisi trolley tetap bisa dilewati.','keys':[['Entry','L14','Dari G3'],['Exit','L2','Ramp ke luar'],['RS','H7','Ratri, baru tampil setelah dinarasikan'],['RH1','R7','Helper 1'],['RH2','H11','Helper 2 hanya bila roster memuatnya'],['PS1','H10','Sentinel jika handling diaktifkan'],['PS2','R10','Unit kedua bila scaling memuatnya']]}
]
html='''<!doctype html><html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Mission G — DM Map Guide</title>
<style>[hidden]{display:none!important}body{font:16px/1.5 system-ui;background:#131d20;color:#edf2ee;margin:0;padding:20px}main{max-width:1400px;margin:auto}h1{font-size:1.7rem;margin-bottom:4px}nav{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}button{background:#263b3c;color:#fff;border:1px solid #688a81;border-radius:7px;padding:10px 15px;cursor:pointer;font:inherit}button[aria-pressed=true]{background:#9c6832}label{display:inline-block;margin:6px 20px 8px 0}#stage{position:relative;line-height:0;max-width:1536px}#map{width:100%;height:auto;display:block}#markers{position:absolute;inset:0}.mark{position:absolute;transform:translate(-50%,-50%);width:3.7%;aspect-ratio:1;min-width:25px;border-radius:50%;padding:0;font:700 clamp(8px,1vw,14px)/1 system-ui;background:#163b43e8;border:2px solid #ffce7d;display:grid;place-items:center}.mark:focus{outline:3px solid white}#keys{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:8px;margin-top:12px}article{background:#203134;border-radius:6px;padding:12px}p{margin:8px 0}.grid{position:absolute;inset:0;pointer-events:none;background-image:linear-gradient(to right,#ffffff44 1px,transparent 1px),linear-gradient(to bottom,#ffffff44 1px,transparent 1px);background-size:calc(100% / 24) calc(100% / 16)}small{color:#c3d3cf}#detail{min-height:30px;background:#2e4543;padding:10px;border-radius:6px}</style>
<main><h1>Mission G — The Empty Lair</h1><small>DM ONLY · proposed staging · 24 × 16 cells · 64 px source grid · 5 ft/cell</small><nav id="nav" aria-label="Pilih map"></nav><label><input id="showKeys" type="checkbox" checked> Tampilkan key DM</label><label><input id="showGrid" type="checkbox"> Grid bantu</label><p id="note"></p><div id="stage"><img id="map" alt=""><div id="grid" class="grid" hidden></div><div id="markers"></div></div><p id="detail" aria-live="polite">Pilih key untuk catatan.</p><section id="keys"></section><p><small>Ini viewer prep lokal, bukan battle tracker Avrae. Tidak mengubah HP/posisi bot. Jangan bagikan layar dengan key DM ke pemain. Script/Combat Preparation adalah rujukan mekanik.</small></p></main>
<script>
const scenes=DATA;
const nav=document.getElementById('nav'),keys=document.getElementById('keys'),markers=document.getElementById('markers'),image=document.getElementById('map');
const buttons=[];
function cellXY(cell){const m=cell.match(/^([A-X])(1[0-6]|[1-9])$/);if(!m)throw Error('Bad cell');return [(m[1].charCodeAt(0)-65+.5)/24*100,(Number(m[2])-.5)/16*100]}
function selectScene(scene){image.src='Maps/'+scene.file;image.alt=scene.title;document.getElementById('note').textContent=scene.note;document.getElementById('detail').textContent='Pilih key untuk catatan.';markers.replaceChildren();keys.replaceChildren();buttons.forEach((b,i)=>b.setAttribute('aria-pressed',String(scenes[i]===scene)));scene.keys.forEach(([name,cell,desc])=>{const [x,y]=cellXY(cell);const b=document.createElement('button');b.className='mark';b.style.left=x+'%';b.style.top=y+'%';b.textContent=name;b.title=cell+' — '+desc;b.setAttribute('aria-label',name+' '+cell+': '+desc);b.onclick=()=>document.getElementById('detail').textContent=name+' · '+cell+' — '+desc;markers.append(b);const a=document.createElement('article'),strong=document.createElement('strong'),p=document.createElement('p');strong.textContent=name+' · '+cell;p.textContent=desc;a.append(strong,p);keys.append(a)});toggleKeys()}
function toggleKeys(){const show=document.getElementById('showKeys').checked;markers.hidden=!show;keys.hidden=!show;document.getElementById('detail').hidden=!show}
scenes.forEach(scene=>{const b=document.createElement('button');b.textContent=scene.title;b.onclick=()=>selectScene(scene);nav.append(b);buttons.push(b)});
document.getElementById('showKeys').onchange=toggleKeys;document.getElementById('showGrid').onchange=e=>document.getElementById('grid').hidden=!e.target.checked;selectScene(scenes[0]);
</script></html>'''.replace('DATA',json.dumps(data,ensure_ascii=False))
(ROOT/'DM Map Guide.html').write_text(html)
(ROOT/'Production/map-key.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
print('Built DM map guide and machine-readable placement key.')
if __name__=='__main__':pass
